CREATE OR REPLACE FUNCTION public.tick_device_wallet_usage(p_handle uuid) RETURNS TABLE(used_seconds integer,resets_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u public.device_wallet_usage; BEGIN INSERT INTO public.device_wallet_usage(credential_handle) VALUES(p_handle) ON CONFLICT DO NOTHING; SELECT * INTO u FROM public.device_wallet_usage WHERE credential_handle=p_handle FOR UPDATE; IF u.window_started+interval '24 hours'<=now() THEN u.window_started:=now();u.used_seconds:=0;u.last_tick:=NULL; END IF; IF u.last_tick IS NOT NULL THEN u.used_seconds:=LEAST(1800,u.used_seconds+GREATEST(0,LEAST(5,floor(extract(epoch FROM now()-u.last_tick))::integer))); END IF; UPDATE public.device_wallet_usage SET window_started=u.window_started,used_seconds=u.used_seconds,last_tick=now(),share_bonus_expires_at=NULL WHERE credential_handle=p_handle; RETURN QUERY SELECT u.used_seconds,u.window_started+interval '24 hours'; END; $$;
REVOKE ALL ON FUNCTION public.tick_device_wallet_usage(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.tick_device_wallet_usage(uuid) TO service_role;